function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (!isValidLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }
  const before = parseCursor(message.before);
  if (message.before !== undefined && before === undefined) {
    return {valid: false, error: 'list_sessions before must have a valid sessionId and updatedAt'};
  }
  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(message.limit !== undefined ? {limit: message.limit} : {}),
      ...(before !== undefined ? {before} : {}),
    },
  };
}

function isValidLimit(limit: unknown): limit is number | undefined {
  if (limit === undefined) return true;
  if (typeof limit !== 'number') return false;
  return Number.isInteger(limit) && limit >= 0;
}

function parseCursor(candidate: unknown): {updatedAt: string | number; sessionId: string} | undefined {
  if (typeof candidate !== 'object' || candidate === null) return undefined;
  const cursor = candidate as Record<string, unknown>;
  if (!isValidCursorSessionId(cursor.sessionId) || !isValidCursorTimestamp(cursor.updatedAt)) return undefined;
  return {updatedAt: cursor.updatedAt, sessionId: cursor.sessionId};
}

const MAX_CURSOR_SESSION_ID_LENGTH = 128;

function isValidCursorSessionId(sessionId: unknown): sessionId is string {
  if (typeof sessionId !== 'string') return false;
  return sessionId.length >= 1 && sessionId.length <= MAX_CURSOR_SESSION_ID_LENGTH;
}

function isValidCursorTimestamp(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt !== 'string' && typeof updatedAt !== 'number') return false;
  return Number.isFinite(new Date(updatedAt).getTime());
}

